@Composable
fun FunkstreckeLogo(modifier: Modifier = Modifier) {
    val scheme = MaterialTheme.colorScheme
    val text = scheme.onSurface
    val accent = scheme.primary
    val second = scheme.secondary
    val vector = remember(text, accent, second) { buildLogo(text, accent, second) }
    Image(imageVector = vector, contentDescription = "Funkstrecke", modifier = modifier)
}

private fun buildLogo(text: Color, accent: Color, second: Color): ImageVector {
    val textNodes = PathParser().parsePathString(TEXT).toNodes()
    return ImageVector.Builder(
        name = "FunkstreckeLogo",
        defaultWidth = LOGO_W.dp,
        defaultHeight = LOGO_H.dp,
        viewportWidth = LOGO_W,
        viewportHeight = LOGO_H,
    ).apply {
        // Zweite Kontur 2 Einheiten nach links, erste 2 nach rechts, darüber die Schrift.
        addGroup(translationX = -2f)
        addPath(textNodes, fill = SolidColor(second))
        clearGroup()
        addGroup(translationX = 2f)
        addPath(textNodes, fill = SolidColor(accent))
        clearGroup()
        addPath(textNodes, fill = SolidColor(text))
        addPath(
            PathParser().parsePathString(ANTENNA).toNodes(),
            stroke = SolidColor(accent),
            strokeLineWidth = 2.13f,
            strokeLineCap = StrokeCap.Round,
            strokeLineJoin = StrokeJoin.Round,
        )
        addPath(PathParser().parsePathString(ANTENNA_DOT).toNodes(), fill = SolidColor(accent))
        addPath(PathParser().parsePathString(WAVE).toNodes(), fill = SolidColor(accent))
    }.build()
}
